    },
    "valid_to": {
      "name": "valid_to",
      "type": "string",
      "title": "Valid To",
      "description": "The last date on which the schedule information is valid. It must be in the ISO 8601 format of YYYY-MM-DD.",
      "constraints": {
        "unique": false
      },
      "example": "2005-01-01",
      "core": "Y",
      "datapackage_type": "date"
    },
    "dtstart": {
      "name": "dtstart",
      "type": "string",
      "title": "Date Start",
      "description": "iCal - The date of the first event is the schedule. Necessary when using the ‘interval’ feature, optional otherwise.",
      "constraints": {
        "unique": false
      },
      "example": "2005-01-01",
      "core": "Y",
      "datapackage_type": "date"
    },
    "timezone": {
      "name": "timezone",
      "type": "number",
      "title": "Timezone",
