      "constraints": {
        "unique": false
      },
      "example": "3"
    },
    "until": {
      "name": "until",
      "type": "string",
      "title": "Until",
      "description": "iCal - The date of the last occurrence of the recurring event.",
      "constraints": {
        "unique": false
      },
      "example": "2005-01-01",
      "datapackage_type": "date"
    },
    "count": {
      "name": "count",
      "type": "number",
      "title": "Count",
      "description": "iCal - The number of times that the event occurs. Use this instead of ‘until’, if appropriate.",
      "constraints": {
        "unique": false
      },
      "example": "3"
    },
    "wkst": {
      "name": "wkst",
      "type": "string",
      "title": "Week Start",
      "description": "iCal - The two-letter code for the day on which the week starts: `MO`, `TU`, `WE`, `TH`, `FR`, `FR`, `SA`, `SU`",
      "constraints": {
        "unique": false
      },
      "example": "TU",
      "enum": [
        "MO",
        "TU",
        "WE",
        "TH",
        "FR",
        "SA",
        "SU"
      ]
    },
    "freq": {
      "name": "freq",
      "type": "string",
      "title": "Frequency",
      "description": "iCal - How often the frequency repeats. Values can be `WEEKLY` or `MONTHLY`",
      "constraints": {
        "unique": false
      },
      "example": "WEEKLY",
      "core": "Y",
      "enum": [
        "WEEKLY",
        "MONTHLY"
      ]
    },
    "interval": {
      "name": "interval",
      "type": "number",
      "title": "Interval",
      "description": "iCal - How often the frequency repeats. For example, and Interval of 2 for a WEEKLY Frequency would represent fortnightly.",
      "constraints": {
        "unique": false
      },
      "example": "1",
      "core": "Y"
    },
    "byday": {
      "name": "byday",
      "type": "string",
      "title": "By Day",
